const cfg = $('Config').first().json;
const wh = $('Webhook Bella').first().json;
const b = wh.body || wh;
const m = b.message || {};
if (b.EventType && b.EventType !== 'messages') return [];
if (m.fromMe || m.wasSentByApi || m.isGroup) return [];
const remetente = String(m.sender_pn || m.chatid || '').replace(/\D/g, '');
const lista = String(cfg.WHITELIST).split(',').map(x => x.replace(/\D/g, '')).filter(Boolean);
if (!remetente || !lista.includes(remetente)) return [];
const texto = String(m.text || m.content || '').trim();
return [{ json: { remetente, nome: m.senderName || '', texto } }];

const cfg = $('Config').first().json;
const f = $('Filtrar').first().json;
if (!f.texto) return [{ json: { pular_llm: true, resposta_direta: 'Oi! Por enquanto eu entendo mensagens de texto 🙂 Escreva o pedido aqui, ou mande por e-mail para ssysbot@gmail.com — lá eu leio foto e PDF também. — Bella', body: { contents: [{ role: 'user', parts: [{ text: 'responda apenas: ok' }] }], generationConfig: { temperature: 0, maxOutputTokens: 5 } } } }];
const reqs = $('Ler REQUISITOS').all().map(i => i.json);
const pedidos = $('Ler PEDIDOS').all().map(i => i.json).filter(p => p && p['Nº PEDIDO']);
let mem = [];
try { mem = $('Ler MEMORIA').all().map(i => i.json).filter(m => m && m.NUMERO && String(m.NUMERO) === String(f.remetente)); } catch (e) {}
const conversa = mem.slice(-8).map(m => (m.PAPEL || '?') + ': ' + String(m.MENSAGEM || '').slice(0, 300)).join('
');
const pend = pedidos.filter(p => String(p['REMETENTE'] || '').indexOf(f.remetente) >= 0 && p['STATUS'] === 'PENDENTE');
const pendTxt = pend.map(p => 'pedido ' + p['Nº PEDIDO'] + ' item ' + p['ITEM Nº'] + ': "' + p['ITEM'] + '" (quant: ' + (p['QUANT.'] || '?') + ' ' + (p['UNID.'] || '') + ') — falta: ' + p['PENDÊNCIAS']).join('
');
const tabela = reqs.map(r => '- ' + r['CATEGORIA'] + ' (palavras-chave: ' + r['PALAVRAS-CHAVE'] + ') => obrigatórios: ' + r['CAMPOS OBRIGATÓRIOS']).join('
');
const SYSTEM = "Você é a Bella, assistente de compras da construtora Prisbel, conversando por WhatsApp. Sua tarefa: classificar a MENSAGEM usando a CONVERSA RECENTE e os ITENS PENDENTES como contexto e, se for pedido ou complemento, extrair os dados. Responda SOMENTE com JSON válido: {"intencao": "PEDIDO"|"COMPLEMENTO"|"STATUS"|"LOCACAO"|"OUTRO", "num_pedido_consultado": numero|null, "pedido": {"obra": "nome"|null, "urgente": true|false, "motivo_urgencia": "texto"|null, "itens": [{"descricao": "...", "quantidade": numero|null, "unidade": "...", "categoria": "da tabela", "campos_faltantes": ["..."]}]} | null, "complementos": [{"num_pedido": numero, "item_num": numero, "descricao_extra": "texto a acrescentar"|null, "quantidade": numero|null, "unidade": "..."|null, "obra": "..."|null, "motivo_urgencia": "..."|null, "pendencias_restantes": ["..."]}] | null}. Definições: PEDIDO = solicita compra de materiais NOVOS; COMPLEMENTO = a mensagem fornece dados que faltavam em itens da lista ITENS PENDENTES — se a Bella acabou de pedir o que falta na CONVERSA RECENTE e a mensagem responde isso, é COMPLEMENTO, NUNCA um pedido novo; STATUS = pergunta sobre andamento de pedido ou cotação; LOCACAO = resposta sobre devolver/renovar equipamentos locados; OUTRO = qualquer outra coisa. Regras de COMPLEMENTO: preencha apenas os campos que a mensagem informa; TODA especificação nova do item (litragem, tipo, cor, dimensão, modelo, tamanho, CA, marca) deve ir em descricao_extra para ficar registrada na descrição — nunca descarte uma informação dada; em pendencias_restantes liste as pendências do item que AINDA ficaram sem resposta (lista vazia se resolveu tudo). Regras de itens: campos obrigatórios ausentes da categoria entram em campos_faltantes; unidade implícita na descrição (sacos, latas, barras, rolos, pacotes, caixas, pares, kg, metros) é unidade VÁLIDA — saco é a unidade padrão de cimento, argamassa, gesso e cal; aplique só os campos que fazem sentido ao subtipo; urgência com justificativa de prazo/cronograma conta como motivo; número de requisição não é quantidade. NUNCA invente dados.";
const user = 'TABELA DE CATEGORIAS:
' + tabela + '

ITENS PENDENTES DESTE REMETENTE:
' + (pendTxt || '(nenhum)') + '

CONVERSA RECENTE:
' + (conversa || '(primeira mensagem)') + '

REMETENTE: ' + (f.nome || f.remetente) + '

MENSAGEM:
' + f.texto;
return [{ json: { pular_llm: false, body: { system_instruction: { parts: [{ text: SYSTEM }] }, contents: [{ role: 'user', parts: [{ text: user }] }], generationConfig: { temperature: 0, maxOutputTokens: 4096, responseMimeType: 'application/json', thinkingConfig: { thinkingBudget: 0 } } } } }];

const cfg = $('Config').first().json;
const f = $('Filtrar').first().json;
const mm = $('Montar').first().json;
const pedidos = $('Ler PEDIDOS').all().map(i => i.json).filter(p => p && p['Nº PEDIDO']);
const memo = (resp, extra) => Object.assign({ resposta: resp, linhas: [], aviso: null, updates: [], num_pedido: '', remetente: f.remetente, texto_usuario: f.texto || '' }, extra || {});
if (mm.pular_llm) return [{ json: memo(mm.resposta_direta) }];
let t = {};
try { const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || ''; t = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch (e) { t = { intencao: 'OUTRO' }; }
if (t.intencao === 'LOCACAO') return [];
if (t.intencao === 'OUTRO') return [{ json: memo('Oi, aqui é a Bella, assistente de compras da Prisbel 🙂 Posso registrar pedidos de material (escreva os itens com quantidades) ou informar o status de um pedido (ex.: "como está o pedido 7?").') }];
const agora = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const dh = String(agora.getDate()).padStart(2,'0') + '/' + String(agora.getMonth()+1).padStart(2,'0') + '/' + agora.getFullYear() + ' ' + String(agora.getHours()).padStart(2,'0') + ':' + String(agora.getMinutes()).padStart(2,'0');
const COLS = ['Nº PEDIDO','DATA/HORA','REMETENTE','NOME','OBRA','URGENTE','MOTIVO URGÊNCIA','ITEM','QUANT.','UNID.','CATEGORIA','STATUS','PENDÊNCIAS','EMAIL_ID','OBS','ITEM Nº'];
if (t.intencao === 'COMPLEMENTO' && Array.isArray(t.complementos) && t.complementos.length) {
  const updates = [], rTxt = []; let pedNum = null, aindaFalta = 0;
  for (const c of t.complementos) {
    const idx = pedidos.findIndex(p => String(p['Nº PEDIDO']) === String(c.num_pedido) && String(p['ITEM Nº']) === String(c.item_num));
    if (idx < 0) continue;
    const p = pedidos[idx];
    pedNum = c.num_pedido;
    if (c.descricao_extra) p['ITEM'] = String(p['ITEM']) + ' ' + c.descricao_extra;
    if (c.quantidade !== null && c.quantidade !== undefined && c.quantidade !== '') p['QUANT.'] = c.quantidade;
    if (c.unidade) p['UNID.'] = c.unidade;
    if (c.obra) p['OBRA'] = c.obra;
    if (c.motivo_urgencia) { p['MOTIVO URGÊNCIA'] = c.motivo_urgencia; }
    const rest = (c.pendencias_restantes || []).filter(x => x);
    p['PENDÊNCIAS'] = rest.join('; ');
    p['STATUS'] = rest.length ? 'PENDENTE' : 'COMPLETO';
    const rn = p.row_number || (idx + 2);
    updates.push({ range: 'PEDIDOS!A' + rn + ':P' + rn, values: [COLS.map(k => (p[k] === undefined || p[k] === null) ? '' : p[k])] });
    rTxt.push((rest.length ? '⚠️' : '✅') + ' ' + c.num_pedido + '.' + c.item_num + ' ' + String(p['ITEM']).slice(0, 60) + (rest.length ? '\n   ainda falta: ' + rest.join('; ') : ''));
    if (rest.length) aindaFalta++;
  }
  if (!updates.length) return [{ json: memo('Não achei o item pendente correspondente 🤔 Me diz o número do pedido e do item (ex.: 12.1) que eu atualizo. — Bella') }];
  const tudoOk = !aindaFalta && !pedidos.some(p => String(p['Nº PEDIDO']) === String(pedNum) && p['STATUS'] === 'PENDENTE');
  let r = '🔄 *Pedido ' + pedNum + ' atualizado!*\n\n' + rTxt.join('\n');
  r += tudoOk ? '\n\nTudo completo — segue para cotação! 🚀' : '\n\nMe manda o que falta que eu completo 😉';
  r += '\n— Bella';
  const aviso = tudoOk ? { para: cfg.EMAIL_DANIELA, assunto: '[Bella] Pedido ' + pedNum + ' completado via WhatsApp', corpo: 'O pedido nº ' + pedNum + ' foi completado pelo requisitante via WhatsApp e está pronto para cotação.\n\nBella — Assistente de Compras | Prisbel Construtora' } : null;
  return [{ json: memo(r, { updates, aviso, num_pedido: pedNum }) }];
}
if (t.intencao === 'STATUS') {
  const numQ = t.num_pedido_consultado ? String(t.num_pedido_consultado) : null;
  let alvo = pedidos;
  if (numQ) alvo = pedidos.filter(p => String(p['Nº PEDIDO']) === numQ);
  if (!alvo.length) return [{ json: memo(numQ ? ('Não encontrei o pedido ' + numQ + ' na fila.') : 'A fila está vazia.') }];
  const porNum = {};
  alvo.forEach(p => { const k = p['Nº PEDIDO']; (porNum[k] = porNum[k] || []).push(p); });
  const nums = Object.keys(porNum).sort((a,b)=>Number(b)-Number(a)).slice(0, numQ ? 1 : 3);
  let r = '📋 Status' + (numQ ? ' do pedido ' + numQ : ' dos últimos pedidos') + ':\n';
  for (const k of nums) {
    const it = porNum[k];
    r += '\n*Pedido ' + k + '* (' + (it[0]['OBRA'] || 'obra —') + '):\n';
    for (const p of it) r += '• ' + (p['ITEM Nº'] ? k + '.' + p['ITEM Nº'] + ' ' : '') + String(p['ITEM']).slice(0, 45) + ' — ' + p['STATUS'] + (p['PENDÊNCIAS'] ? ' (falta: ' + p['PENDÊNCIAS'] + ')' : '') + '\n';
  }
  r += '\n— Bella';
  return [{ json: memo(r, { num_pedido: numQ || '' }) }];
}
const ped = t.pedido || {};
let num = 0; for (const p of pedidos) { const n = Number(p['Nº PEDIDO']); if (n > num) num = n; } num++;
const urg = ped.urgente === true; const urgSemMotivo = urg && !ped.motivo_urgencia;
const linhas = [], pend2 = [], comp = []; let seq = 0;
for (const it of (ped.itens || [])) {
  const faltas = (it.campos_faltantes || []).slice();
  if (urgSemMotivo && !faltas.includes('motivo da urgência')) faltas.push('motivo da urgência');
  const status = faltas.length ? 'PENDENTE' : 'COMPLETO';
  linhas.push({ 'Nº PEDIDO': num, 'ITEM Nº': ++seq, 'DATA/HORA': dh, 'REMETENTE': 'WhatsApp +' + f.remetente, 'NOME': f.nome || '', 'OBRA': ped.obra || '', 'URGENTE': urg ? 'SIM' : 'NÃO', 'MOTIVO URGÊNCIA': ped.motivo_urgencia || '', 'ITEM': it.descricao || '', 'QUANT.': it.quantidade ?? '', 'UNID.': it.unidade || '', 'CATEGORIA': it.categoria || 'GERAL', 'STATUS': status, 'PENDÊNCIAS': faltas.join('; '), 'EMAIL_ID': 'whatsapp', 'OBS': '' });
  (faltas.length ? pend2 : comp).push({ it, faltas });
}
if (!linhas.length) return [{ json: memo('Entendi que é um pedido, mas não consegui identificar os itens 🤔 Pode escrever um item por linha, com quantidade? — Bella') }];
let r = '📋 *Pedido ' + num + ' registrado!*' + (ped.obra ? ' (obra ' + ped.obra + ')' : '') + '\n';
for (const l of linhas) r += '\n' + (l['STATUS'] === 'COMPLETO' ? '✅' : '⚠️') + ' ' + num + '.' + l['ITEM Nº'] + ' ' + l['ITEM'] + (l['PENDÊNCIAS'] ? '\n   falta: ' + l['PENDÊNCIAS'] : '');
if (pend2.length) r += '\n\nMe manda o que falta que eu completo o pedido 😉';
else r += '\n\nTudo completo — segue para cotação!';
r += '\n— Bella';
const aviso = { para: cfg.EMAIL_DANIELA, assunto: '[Bella] Pedido ' + num + ' registrado via WhatsApp — ' + comp.length + ' ok / ' + pend2.length + ' pendente(s)', corpo: 'Pedido nº ' + num + ' registrado via WhatsApp por ' + (f.nome || f.remetente) + '.\nObra: ' + (ped.obra || '—') + '\n\n' + linhas.map(l => '• [' + l['STATUS'] + '] ' + l['ITEM'] + (l['PENDÊNCIAS'] ? ' — falta: ' + l['PENDÊNCIAS'] : '')).join('\n') + '\n\nBella — Assistente de Compras | Prisbel Construtora' };
return [{ json: memo(r, { linhas, aviso, num_pedido: num }) }];

const d = $json;
if (!d.linhas || !d.linhas.length) return [];
return d.linhas.map(l => ({ json: l }));

const d = $('Processar').first().json;
if (!d.aviso) return [];
return [{ json: d.aviso }];

const j = $('Processar').first().json;
if (!j || !j.resposta) return [];
const agora = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const dh = String(agora.getDate()).padStart(2,'0') + '/' + String(agora.getMonth()+1).padStart(2,'0') + '/' + agora.getFullYear() + ' ' + String(agora.getHours()).padStart(2,'0') + ':' + String(agora.getMinutes()).padStart(2,'0');
const np = j.num_pedido || '';
return [{ json: { valores: [[j.remetente, dh, 'USUARIO', String(j.texto_usuario || '').slice(0, 500), np], [j.remetente, dh, 'BELLA', String(j.resposta || '').slice(0, 500), np]] } }];
